#include <iostream>
#include <iomanip>
using namespace std;

int main() {
    int c;
    cin >> c;

    // 关键：9.0 是浮点数，整个表达式才会按小数运算。
    // 写成 9 / 5 的话会做整数除法，得到 1。
    double f = c * 9.0 / 5 + 32;

    // fixed + setprecision(2) = 保留 2 位小数（默认还会四舍五入）
    cout << fixed << setprecision(2) << f << endl;
    return 0;
}
